        airdrop = new airDrop();
        maliciousToken = new MaliciousToken(
            airdrop,
            address(this),
            v,
            decimals,
            recipient2
        );
    }

    function testReentrancy() public {
        address[] memory tos = new address[](1);
        tos[0] = recipient1;

        vm.recordLogs();
        airdrop.transfer(address(this), address(maliciousToken), tos, v, decimals);

